function videoTime(seconds){if(!Number.isFinite(seconds))return '待统计';seconds=Math.max(0,Math.round(seconds));if(seconds<60)return seconds+'秒';const m=Math.floor(seconds/60),s=seconds%60;return m+'分'+(s?s+'秒':'');}
function videoTimeRange(range){return range?.length===2?videoTime((range[0]+range[1])/2):'';}
function fillVideoTiming(){const box=document.querySelector('#videoTiming');if(!box)return;const target=shotVideoTarget();if(!target)return;const job=target.videoJob||selectedShotVideo(target),version=selectedShotVideo(target);if(!job){box.innerHTML='<p class="subtle">生成后显示实时采样步数、已用时间及预计剩余时间。</p>';return}const p=job.progress||{},t=job.timing||{},finished=['completed','failed','cancelled'].includes(job.status),start=Date.parse(job.created_at),end=finished?Date.parse(job.finished_at):Date.now();const elapsed=Number.isFinite(start)&&Number.isFinite(end)?Math.max(0,(end-start)/1000):t.elapsed_seconds;
const phase=job.status==='completed'?'已完成':job.status==='failed'?'生成失败':job.status==='queued'?'排队等待':job.status==='preparing'?'准备并上传参考图片':job.status==='saving'?'读取、裁切并保存视频':p.label||'加载模型或分析参考图';
let remaining='';if(!finished){if(job.status==='queued')remaining=t.estimated_total_range_seconds?'开始执行后约 '+videoTimeRange(t.estimated_total_range_seconds)+'，不含排队时间':'等待前方任务，暂不能估计排队时间';else if(Number.isFinite(t.remaining_seconds)){const since=Math.max(0,(Date.now()-(job.timing_received_at||Date.now()))/1000),stale=since>15;remaining=stale?'正在等待最新进度，暂不倒数':('预计还需约 '+videoTimeRange(t.remaining_range_seconds||[t.remaining_seconds,t.remaining_seconds])+'（含解码、合成与保存）'+(t.estimate_overdue?'；当前阶段比参考耗时更久，估算已上调':''));}else if(t.estimate_overdue)remaining='已超过历史估算，任务仍在处理';else if(t.remaining_range_seconds){const observed=job.timing_received_at||Date.now(),since=(Date.now()-observed)/1000;const range=t.remaining_range_seconds.map(n=>Math.max(0,n-since));remaining=range[1]>0?'预计还需约 '+videoTimeRange(range):'接近历史估算时间，仍需等待实际完成';}else if(t.estimated_total_range_seconds)remaining='本次执行预计约 '+videoTimeRange(t.estimated_total_range_seconds);else remaining='正在收集数据，暂无法估算';}
const step=Number.isFinite(p.step)?'采样第 '+p.step+' / '+p.total_steps+' 步':job.status==='completed'?'采样 '+(job.steps||4)+' / '+(job.steps||4)+' 步已完成':'采样尚未开始';const output=job.status==='completed'?(job.actual_duration_seconds??version?.actual_duration_seconds):null;
const gpuText=typeof generationGpuLabel==='function'?generationGpuLabel(job):'GPU未记录';
box.innerHTML='<p class="subtle" style="margin:0 0 12px">执行设备：'+esc(gpuText)+'</p><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><b>'+esc(phase)+'</b><span>'+esc(step)+'</span></div>'+(Number.isFinite(p.step)?'<progress max="'+p.total_steps+'" value="'+p.step+'" style="width:100%;margin-top:12px;accent-color:var(--green)"></progress>':'')+'<p style="margin:10px 0">'+(finished?'总耗时：':'已用时间：')+esc(videoTime(elapsed))+'</p>'+(remaining?'<p class="subtle">'+esc(remaining)+((t.estimate_basis==='live_steps'?'（按本次实际每步耗时动态估算）':t.estimate_basis==='first_step'?'（依据本次首步耗时初估，后续继续校准）':t.estimate_samples?'（参考 '+t.estimate_samples+' 次同分辨率、同模式任务，并按实际帧数调整）':'（按分辨率、生成帧数和采样步数初估）'))+'</p>':'')+(Number.isFinite(t.postprocessing_seconds)?'<p class="subtle">采样后处理耗时：'+videoTime(t.postprocessing_seconds)+'</p>':!finished&&Number.isFinite(t.postprocessing_estimate_seconds)?'<p class="subtle">采样后解码、合成及保存预计：'+videoTime(t.postprocessing_estimate_seconds)+'</p>':'')+'<p class="subtle">计划视频时长：'+esc(videoTime(job.duration||target.duration))+(output!=null?' · 实际视频时长：'+Number(output).toFixed(2)+'秒':'')+'</p>'+(job.status==='running'&&!Number.isFinite(p.step)?'<small class="subtle">模型加载和参考图编码阶段没有采样步数；收到采样事件后自动更新。</small>':'');
}
const videoTimingFetched=new Set();
const shotsBeforeTiming=shots;shots=function(){shotsBeforeTiming();const parent=document.querySelector('#shotVideoPanel'),target=shotVideoTarget();if(!parent||!target)return;const box=document.createElement('div');box.id='videoTiming';box.style.cssText='padding:14px;margin:12px 0;border:1px solid #344254;border-radius:8px;background:#101923';document.querySelector('#shotVideoStatus').after(box);fillVideoTiming();const job=target.videoJob||selectedShotVideo(target);if(job?.id&&job.status!=='preparing'&&!videoTimingFetched.has(job.id)){videoTimingFetched.add(job.id);frontFetch('/api/video/'+job.id).then(latest=>{latest.timing_received_at=Date.now();if(target.videoJob?.id===latest.id)target.videoJob=latest;const i=target.videoVersions?.findIndex(v=>v.id===latest.id);if(i>=0)target.videoVersions[i]=latest;save();if(tab===2&&shotVideoTarget()===target)fillVideoTiming();}).catch(()=>videoTimingFetched.delete(job.id));}};
const applyShotVideoBeforeTiming=applyShotVideo;applyShotVideo=function(target,job){job.timing_received_at=Date.now();applyShotVideoBeforeTiming(target,job);if(tab===2&&shotVideoTarget()===target)fillVideoTiming();};setInterval(()=>{if(tab===2)fillVideoTiming()},1000);render();
